def p_code(iid):
    """biome code base of an island: 1A 1100 ... 1E 1500 (spec 3.2 / 5.1); band 50 = the middle of its 100-wide range"""
    return 1000 + 100 * (ord(iid[1]) - ord("A") + 1)


